import numpy as np
e=eps; t=T; s=sigma
ea=np.arange(-2,3.01,0.5); tb=np.arange(-2,6.01,0.5)
cols=[];names=[]
for a in ea:
    for b in tb:
        cols.append(e**a*t**b); names.append(('e^%g'%a,'T^%g'%b))
extraE={'exp(-e)':np.exp(-e),'log e':np.log(e),'e/(1+e)':e/(1+e),'exp(e)':np.exp(e),'1/(1+e)':1/(1+e)}
extraT={'exp(-T)':np.exp(-t),'exp(T)':np.exp(t),'log T':np.log(t),'exp(-1/T)':np.exp(-1/t),'1/(1+T)':1/(1+t)}
for fn,fv in extraE.items():
    for b in tb:
        cols.append(fv*t**b); names.append((fn,'T^%g'%b))
for gn,gv in extraT.items():
    for a in ea:
        cols.append(e**a*gv); names.append(('e^%g'%a,gn))
M=np.column_stack(cols); K=M.shape[1]
iu=np.triu_indices(K,1)
res=[]
for c3 in [0.9,0.95,1.0,1.05,1.1]:
    B=np.column_stack([1/e,(e/(1+c3*e))*t**3])
    Q,_=np.linalg.qr(B)
    Mr=M-Q@(Q.T@M); sr=s-Q@(Q.T@s)
