    rss=np.where(ok,(sr@sr)-(c1*h[i]+c2*h[j]),np.inf)
    order=np.argsort(rss)[:3]
    for k in order:
        res.append((rss[k]/np.sum((s-s.mean())**2),c3,names[i[k]],names[j[k]],round(c1[k],4),round(c2[k],4)))
